module score_calculator (\n    input [3:0] N,\n    input [63:0] x [0:7],\n    input [63:0] y [0:7],\n    output reg [63:0] result\n);\n    always @(*) begin\n        result = 64'd0;\n        if (N >= 3'd3) begin\n            for (integer i = 0; i < N; i = i + 1) begin\n                for (integer j = i + 1; j < N; j = j + 1) begin\n                    for (integer k = j + 1; k < N; k = k + 1) begin\n                        result = (result + twice_area(i, j, k)) % 64'd1000003;\n                    end\n                end\n            end\n        end\n    end\n\n    function automatic [63:0] twice_area;\n        input [2:0] i;\n        input [2:0] j;\n        input [2:0] k;\n        reg signed [63:0] x1, y1, x2, y2, x3, y3;\n        reg signed [63:0] area;\n        reg [63:0] abs_area;\n    begin\n        x1 = x[i];\n        y1 = y[i];\n        x2 = x[j];\n        y2 = y[j];\n        x3 = x[k];\n        y3 = y[k];\n        area = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);\n        abs_area = (area < 0) ? -area : area;\n        twice_area = abs_area;\n    end\n    endfunction\nendmodule